.si-detail-page{max-width:1440px;margin:auto}.si-detail-page .si-header{min-height:115px}.si-back{gap:9px;margin:15px 0 75px;font-size:11px;font-weight:700}.si-back img{transform:rotate(180deg)}.si-detail-hero{display:grid;grid-template-columns:1.1fr .9fr;gap:60px;padding-bottom:65px}.si-detail-hero h1{max-width:700px;font-size:clamp(64px,10vw,150px);font-weight:400;letter-spacing:-.085em;line-height:.83}.si-detail-hero>div:first-child>p:last-child{max-width:590px;margin-top:32px;color:#343436;font-size:clamp(17px,2vw,25px);line-height:1.28}.si-detail-labels{grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;gap:20px;padding-top:35px}.si-detail-label{display:flex;min-height:110px;flex-direction:column;justify-content:space-between;padding:15px 0;border-top:1px solid var(--si-line)}.si-detail-label span{gap:8px;color:#777;font-size:10px;letter-spacing:.05em;text-transform:uppercase}.si-detail-label strong{max-width:190px;font-size:13px;line-height:1.3}.si-detail-image{overflow:hidden;border-radius:20px}.si-detail-image img{width:100%;height:min(65vw,720px);object-fit:cover}.si-detail-story{grid-template-columns:1fr 1fr;gap:14%;padding:120px 9%}.si-detail-story h2,.si-system-copy h2{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3;font-size:clamp(31px,4vw,57px);font-weight:400;letter-spacing:-.055em;line-height:.98}.si-detail-story>p{max-width:490px;padding-top:42px;color:#454549;font-size:16px}.si-system{grid-template-columns:1fr 1fr;gap:16px;align-items:stretch;padding:0 9% 110px}.si-system-card{display:flex;min-height:500px;flex-direction:column;justify-content:space-between;padding:26px;border-radius:18px;color:#fff}.si-system-card span{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase}.si-system-card b{font-size:clamp(160px,20vw,310px);font-weight:400;letter-spacing:-.12em;line-height:.72}.si-system-copy{display:flex;min-height:500px;flex-direction:column;justify-content:center;padding:9%}.si-system-copy>p:not(.si-eyebrow){max-width:430px;margin-top:28px;color:#56565a}.si-swatches{gap:9px;margin-top:38px}.si-swatches i{width:35px;height:35px;border-radius:50%;background:#141414}.si-swatches i:nth-child(3){background:#d6d4ce}.si-swatches i:nth-child(4){background:#f1eee6}.si-gallery{grid-template-columns:1fr 1fr;gap:16px;padding-bottom:120px}.si-gallery figure{min-height:430px;overflow:hidden;border-radius:18px}.si-gallery figure:first-child{grid-column:1/3;min-height:680px}.si-gallery figure.is-tall{min-height:630px}.si-gallery img{width:100%;height:100%;object-fit:cover;transition:transform .6s cubic-bezier(.16,1,.3,1)}.si-gallery figure:hover img{transform:scale(1.025)}.si-detail-outcome{max-width:970px;padding:0 0 130px}.si-detail-outcome h2{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3;margin-bottom:42px;font-size:clamp(36px,5vw,72px);font-weight:400;letter-spacing:-.065em;line-height:.96}.si-detail-page .si-footer>a{display:inline-flex;align-items:center;gap:9px;font-weight:700}
